def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result") or {}
    outcome = result.get("outcome")
    credit_limit = result.get("credit_limit", 0)

    # Map API v2 outcomes to actions
    if outcome == "approved":
        action = "issue"
        limit = credit_limit
    elif outcome == "declined":
        action = "decline"
        limit = 0
    elif outcome == "manual_review":
        action = "queue_review"
        limit = 0
    else:
        # Unknown/missing outcome: safe default is manual review
        action = "queue_review"
        limit = 0

    # Network referral rule: self_employed with requested_limit strictly above
    # 6000 must be queue_review instead of issued. A decline stays a decline.
    if action == "issue":
        employment = app.get("employment")
        requested_limit = app.get("requested_limit", 0)
        if employment == "self_employed" and requested_limit > 6000:
            action = "queue_review"
            limit = 0

    return {"action": action, "limit": limit}

